insert into public.projects (slug, title, category, label, color, thumbnail, tagline, description, features, technologies, sort_order, is_published) values
  ('borrowit', 'BorrowIt', 'uiux', '{"id":"🎨 UI/UX Mobile","en":"🎨 UI/UX Mobile"}'::jsonb, '#6C5CE7', '/images/projects/borrowit/thumbnail.png', '{"id":"Platform Peminjaman Barang Kampus","en":"Campus Item Lending Platform"}'::jsonb, '{"id":"Desain antarmuka aplikasi mobile untuk memudahkan peminjaman barang antar mahasiswa di lingkungan kampus. Dilengkapi fitur verifikasi KTM untuk keamanan dan kepercayaan, chat real-time, sistem rating, serta pencarian barang berbasis lokasi. Didesain dengan tampilan modern dan bersih yang mengutamakan kemudahan penggunaan.","en":"Mobile app interface design to facilitate item lending among campus students. Features KTM verification for security, real-time chat, rating system, and location-based search. Designed with a modern, clean look prioritizing ease of use."}'::jsonb, '{"id":["Verifikasi KTM","Kategori Barang","Chat Real-time","Sistem Rating","Pencarian Berbasis Lokasi"],"en":["KTM Verification","Item Categories","Real-time Chat","Rating System","Location-based Search"]}'::jsonb, array['Figma', 'UI/UX Design', 'Mobile Design', 'Prototyping'], 1, true),
  ('ekost', 'E-Kost Manager', 'web', '{"id":"🌐 Web App","en":"🌐 Web App"}'::jsonb, '#0C1B3A', '/images/projects/ekost/thumbnail.png', '{"id":"Sistem Manajemen Properti Kost","en":"Boarding House Management System"}'::jsonb, '{"id":"Platform web untuk manajemen kost yang komprehensif. Memungkinkan pemilik kost mengelola penyewa, melacak pembayaran, dan menangani keluhan secara digital. Penyewa dapat mencari properti, melakukan pembayaran, dan berkomunikasi dengan pemilik secara seamless. Dibangun menggunakan Laravel dengan fitur lengkap untuk kedua sisi pengguna.","en":"Comprehensive boarding house management web platform. Allows owners to manage tenants, track payments, and handle complaints digitally. Tenants can search properties, make payments, and communicate with owners seamlessly. Built with Laravel with full features for both user roles."}'::jsonb, '{"id":["Dashboard Pemilik","Portal Penyewa","Pelacakan Pembayaran","Daftar Properti","Sistem Testimoni"],"en":["Owner Dashboard","Tenant Portal","Payment Tracking","Property Listings","Testimonial System"]}'::jsonb, array['Laravel', 'PHP', 'MySQL', 'Bootstrap', 'JavaScript'], 2, true),
  ('melodean', 'Melodean', 'uiux', '{"id":"🎨 UI/UX Mobile","en":"🎨 UI/UX Mobile"}'::jsonb, '#0066CC', '/images/projects/melodean/thumbnail.png', '{"id":"E-Learning Interaktif untuk Siswa","en":"Interactive E-Learning for Students"}'::jsonb, '{"id":"Desain antarmuka platform e-learning mobile yang menarik untuk siswa SMA. Menampilkan elemen gamifikasi termasuk poin, badge, dan leaderboard untuk memotivasi proses belajar. Dilengkapi manajemen jadwal, modul pembelajaran berbasis mata pelajaran, dan pemindaian absensi berbasis QR. Didesain dengan pendekatan playful namun tetap fungsional.","en":"Attractive mobile e-learning interface design for high school students. Features gamification elements including points, badges, and leaderboard to motivate learning. Includes schedule management, subject-based learning modules, and QR-based attendance scanning. Designed with a playful yet functional approach."}'::jsonb, '{"id":["Sistem Gamifikasi","Modul Pelajaran","Absensi QR","Leaderboard","Koleksi Badge"],"en":["Gamification System","Learning Modules","QR Attendance","Leaderboard","Badge Collection"]}'::jsonb, array['Figma', 'UI/UX Design', 'Mobile Design', 'Gamification'], 3, true),
  ('nusantara', 'Nusantara Legacy', 'uiux', '{"id":"🎨 UI/UX Web","en":"🎨 UI/UX Web"}'::jsonb, '#0F3D3E', '/images/projects/nusantara/thumbnail.png', '{"id":"Platform Warisan Budaya Indonesia","en":"Indonesian Cultural Heritage Platform"}'::jsonb, '{"id":"Desain antarmuka platform web yang didedikasikan untuk melestarikan dan membagikan warisan budaya Indonesia. Menampilkan artikel budaya, podcast sejarah (Historiccast), circle komunitas, dan aktivitas interaktif. Pengguna dapat menjelajahi, berkontribusi, dan belajar tentang keragaman budaya Indonesia. Didesain dengan nuansa budaya yang kuat dan navigasi intuitif.","en":"Web platform interface design dedicated to preserving and sharing Indonesian cultural heritage. Features cultural articles, history podcasts (Historiccast), community circles, and interactive activities. Users can explore, contribute, and learn about Indonesia''s cultural diversity. Designed with a strong cultural feel and intuitive navigation."}'::jsonb, '{"id":["Artikel Budaya","Podcast Historiccast","Circle Komunitas","Aktivitas Interaktif","Pencarian & Eksplorasi"],"en":["Cultural Articles","Historiccast Podcast","Community Circle","Interactive Activities","Search & Exploration"]}'::jsonb, array['Figma', 'UI/UX Design', 'Web Design', 'Prototyping'], 4, true),
  ('paynow', 'PayNow', 'uiux', '{"id":"🎨 UI/UX Mobile","en":"🎨 UI/UX Mobile"}'::jsonb, '#3B3F8C', '/images/projects/paynow/thumbnail.jpg', '{"id":"Dompet Digital & Solusi Pembayaran","en":"Digital Wallet & Payment Solution"}'::jsonb, '{"id":"Desain antarmuka aplikasi dompet digital modern yang memungkinkan transfer uang cepat dan aman, pembayaran tagihan, dan pelacakan keuangan. Dilengkapi fitur top-up, transfer internasional, ringkasan keuangan, reward voucher, dan autentikasi biometrik untuk keamanan lebih baik. Didesain dengan fokus pada kepercayaan dan kemudahan transaksi.","en":"Modern digital wallet app interface design enabling fast and secure money transfers, bill payments, and financial tracking. Features top-up, international transfers, financial summaries, reward vouchers, and biometric authentication. Designed with a focus on trust and ease of transaction."}'::jsonb, '{"id":["Dompet Digital","Pembayaran Tagihan","Pelacakan Keuangan","Reward Voucher","Autentikasi Biometrik"],"en":["Digital Wallet","Bill Payment","Financial Tracking","Reward Vouchers","Biometric Authentication"]}'::jsonb, array['Figma', 'UI/UX Design', 'Mobile Design', 'FinTech'], 5, true),
  ('warasa', 'Warasa', 'web', '{"id":"🌐 Web & Mobile App","en":"🌐 Web & Mobile App"}'::jsonb, '#FF6B35', '/images/projects/warasa/thumbnail.png', '{"id":"Asisten E-Commerce Berbasis AI","en":"AI-Powered E-Commerce Assistant"}'::jsonb, '{"id":"Platform web dan mobile berbasis AI yang dirancang untuk membantu seller Shopee mengoptimalkan bisnis online mereka. Dilengkapi fitur smart product generation, kalkulator ROAS, SEO scoring, analisis kompetitor, dan tools bulk export. Dipercaya oleh 10.000+ seller online untuk meningkatkan performa toko mereka.","en":"AI-powered web and mobile platform designed to help Shopee sellers optimize their online business. Features smart product generation, ROAS calculator, SEO scoring, competitor analysis, and bulk export tools. Trusted by 10,000+ online sellers to improve their store performance."}'::jsonb, '{"id":["Generator Produk AI","Kalkulator ROAS","Optimasi SEO","Analisis Kompetitor","Ekspor Massal"],"en":["AI Product Generator","ROAS Calculator","SEO Optimization","Competitor Analysis","Bulk Export"]}'::jsonb, array['Laravel', 'Flutter', 'AI/ML', 'Shopee API', 'JavaScript'], 6, true),
  ('spr', 'Emotion-Based Music Recommender', 'data', '{"id":"📊 Data Analysis","en":"📊 Data Analysis"}'::jsonb, '#10B981', '/images/projects/spr/chart_1.png', '{"id":"Sistem Rekomendasi Musik Berbasis Emosi","en":"Emotion-Based Music Recommendation System"}'::jsonb, '{"id":"Sistem rekomendasi musik berbasis AI yang dapat dijelaskan, menggunakan attention-based emotion preference learning. Sistem mendeteksi emosi pengguna dari input teks, menerapkan TF-IDF + Logistic Regression untuk klasifikasi sentimen, menggunakan analisis fitur berbobot attention, dan memberikan rekomendasi lagu berbasis konten dengan transparansi XAI (Explainable AI) penuh.","en":"An explainable AI-based music recommendation system using attention-based emotion preference learning. The system detects user emotions from text input, applies TF-IDF + Logistic Regression for sentiment classification, uses attention-weighted feature analysis, and provides content-based song recommendations with full XAI transparency."}'::jsonb, '{"id":["Deteksi Emosi","Pembobotan Berbasis Attention","Content-Based Filtering","Explainable AI (XAI)","Klasifikasi Sentimen","Evaluasi Top-K"],"en":["Emotion Detection","Attention-Based Weighting","Content-Based Filtering","Explainable AI (XAI)","Sentiment Classification","Top-K Evaluation"]}'::jsonb, array['Python', 'Scikit-learn', 'Pandas', 'Matplotlib', 'TF-IDF', 'Logistic Regression'], 7, true),
  ('pixora', 'Pixora', 'web', '{"id":"🌐 Web & Mobile App","en":"🌐 Web & Mobile App"}'::jsonb, '#E11D48', '/images/projects/pixora/thumbnail.png', '{"id":"Platform Booking Studio Fotografi","en":"Photography Studio Booking Platform"}'::jsonb, '{"id":"Platform booking studio fotografi full-stack yang menghubungkan pelanggan dengan layanan fotografi profesional. Versi web dibangun dengan Laravel menyediakan landing page, katalog paket, kalender booking interaktif, pembayaran online via Midtrans (VA, E-Wallet, QRIS), invoice digital, admin dashboard, serta integrasi AI assistant. Versi mobile dibangun dengan Flutter menghadirkan pengalaman booking yang seamless dengan fitur browse paket, kalender ketersediaan, pembayaran dalam aplikasi, chatbot AI, Google Sign-In, dan manajemen profil lengkap dengan riwayat booking.","en":"Full-stack photography studio booking platform connecting customers with professional photography services. Web version built with Laravel provides landing page, package catalog, interactive booking calendar, online payment via Midtrans (VA, E-Wallet, QRIS), digital invoices, admin dashboard, and AI assistant integration. Mobile version built with Flutter delivers a seamless booking experience with package browsing, an availability calendar, in-app payments, an AI chatbot, Google Sign-In, and full profile management with booking history."}'::jsonb, '{"id":["Booking Online","Pembayaran Midtrans","AI Assistant","Kalender Interaktif","Admin Dashboard","Mobile App Flutter"],"en":["Online Booking","Midtrans Payment","AI Assistant","Interactive Calendar","Admin Dashboard","Flutter Mobile App"]}'::jsonb, array['Laravel', 'Flutter', 'MySQL', 'Midtrans', 'AI Integration', 'Google Auth'], 8, true),
  ('qa-cazh', 'Quality Assurance — PT Cazh', 'qa', '{"id":"🔍 Quality Assurance","en":"🔍 Quality Assurance"}'::jsonb, '#0EA5E9', '/images/projects/qa-cazh/thumbnail.png', '{"id":"Pengujian Kualitas Produk Digital","en":"Digital Product Quality Testing"}'::jsonb, '{"id":"Proyek magang sebagai Quality Assurance di PT Cazh Purwokerto (Juli — Agustus 2026). Bertanggung jawab melakukan pengujian fungsional dan non-fungsional pada produk digital perusahaan, menyusun test case dan test scenario, melaporkan bug melalui bug tracking system, serta memastikan kualitas produk sebelum rilis ke production environment.","en":"Internship project as Quality Assurance at PT Cazh Purwokerto (July — August 2026). Responsible for conducting functional and non-functional testing on digital products, preparing test cases and test scenarios, reporting bugs through bug tracking system, and ensuring product quality before release to production."}'::jsonb, '{"id":["Pengujian Fungsional","Penyusunan Test Case","Pelaporan Bug","Regression Testing","Validasi UI/UX"],"en":["Functional Testing","Test Case Design","Bug Reporting","Regression Testing","UI/UX Validation"]}'::jsonb, array['Manual Testing', 'Test Case', 'Bug Tracking', 'Functional Testing', 'Regression Testing'], 9, true);

