insert into public.project_steps (project_id, title, description, sort_order)
select p.id, v.title, v.description, v.sort_order
from (values
  ('borrowit', '{"id":"Riset Pengguna & Identifikasi Masalah","en":"User Research & Problem Identification"}'::jsonb, '{"id":"Melakukan riset terhadap mahasiswa untuk memahami permasalahan peminjaman barang di lingkungan kampus, termasuk survei kebutuhan dan analisis pain points.","en":"Researching students to understand item lending issues on campus, including needs surveys and pain point analysis."}'::jsonb, 1),
  ('borrowit', '{"id":"Arsitektur Informasi","en":"Information Architecture"}'::jsonb, '{"id":"Menyusun struktur informasi aplikasi meliputi sitemap, user flow peminjaman dan pengembalian, serta hierarki navigasi.","en":"Structuring the app including sitemap, lending/return user flows, and navigation hierarchy."}'::jsonb, 2),
  ('borrowit', '{"id":"Wireframing & Prototipe Awal","en":"Wireframing & Early Prototype"}'::jsonb, '{"id":"Membuat wireframe untuk setiap halaman utama seperti home, search, detail barang, dan activity tracking sebagai kerangka awal desain.","en":"Creating wireframes for main pages: home, search, item detail, and activity tracking."}'::jsonb, 3),
  ('borrowit', '{"id":"Desain UI & Design System","en":"UI Design & Design System"}'::jsonb, '{"id":"Mendesain antarmuka high-fidelity di Figma dengan design system yang konsisten meliputi color palette, typography, spacing, dan komponen reusable.","en":"Designing high-fidelity interfaces in Figma with consistent design system including color palette, typography, and reusable components."}'::jsonb, 4),
  ('borrowit', '{"id":"Prototyping & Pengujian Pengguna","en":"Prototyping & User Testing"}'::jsonb, '{"id":"Membangun interactive prototype dan melakukan usability testing dengan target pengguna untuk validasi alur serta perbaikan UI/UX berdasarkan feedback.","en":"Building interactive prototype and conducting usability testing with target users for validation and UI/UX improvements."}'::jsonb, 5),
  ('ekost', '{"id":"Analisis Kebutuhan","en":"Requirements Analysis"}'::jsonb, '{"id":"Menganalisis kebutuhan sistem manajemen kost dari sisi pemilik dan penyewa, termasuk fitur pembayaran, keluhan, dan pencarian properti.","en":"Analyzing boarding house management needs from owner and tenant perspectives, including payment, complaints, and property search features."}'::jsonb, 1),
  ('ekost', '{"id":"Perancangan Database","en":"Database Design"}'::jsonb, '{"id":"Merancang skema database relasional dengan tabel users, properties, rooms, payments, complaints, dan testimonials beserta relasinya.","en":"Designing relational database schema with users, properties, rooms, payments, complaints, and testimonials tables."}'::jsonb, 2),
  ('ekost', '{"id":"Pengembangan Backend","en":"Backend Development"}'::jsonb, '{"id":"Mengembangkan backend menggunakan Laravel dengan fitur autentikasi multi-role (pemilik/penyewa), CRUD properti, dan sistem pembayaran digital.","en":"Developing backend using Laravel with multi-role authentication (owner/tenant), property CRUD, and digital payment system."}'::jsonb, 3),
  ('ekost', '{"id":"Implementasi Frontend","en":"Frontend Implementation"}'::jsonb, '{"id":"Membangun antarmuka responsif dengan Bootstrap dan JavaScript untuk dashboard pemilik, portal penyewa, serta halaman pencarian properti.","en":"Building responsive interface with Bootstrap and JavaScript for owner dashboard, tenant portal, and property search."}'::jsonb, 4),
  ('ekost', '{"id":"Pengujian & Deployment","en":"Testing & Deployment"}'::jsonb, '{"id":"Melakukan pengujian fungsional pada setiap modul, perbaikan bug, dan deployment ke server production.","en":"Functional testing on every module, bug fixes, and deployment to production server."}'::jsonb, 5),
  ('melodean', '{"id":"Riset Pengguna & Persona","en":"User Research & Persona"}'::jsonb, '{"id":"Melakukan riset terhadap siswa SMA untuk memahami motivasi belajar dan preferensi penggunaan aplikasi e-learning, lalu menyusun user persona.","en":"Researching high school students to understand learning motivation and e-learning app preferences, then creating user personas."}'::jsonb, 1),
  ('melodean', '{"id":"Strategi Gamifikasi","en":"Gamification Strategy"}'::jsonb, '{"id":"Merancang sistem gamifikasi meliputi poin, badge, dan leaderboard untuk meningkatkan engagement dan motivasi belajar siswa.","en":"Designing gamification system including points, badges, and leaderboard to increase student engagement and motivation."}'::jsonb, 2),
  ('melodean', '{"id":"Desain UI/UX","en":"UI/UX Design"}'::jsonb, '{"id":"Mendesain antarmuka yang menarik dan ramah pengguna di Figma dengan pendekatan playful namun tetap fungsional untuk konteks edukasi.","en":"Designing attractive and user-friendly interfaces in Figma with a playful yet functional approach for educational context."}'::jsonb, 3),
  ('melodean', '{"id":"Prototyping Interaktif","en":"Interactive Prototyping"}'::jsonb, '{"id":"Membangun prototype interaktif dengan micro-interactions, animasi transisi, dan simulasi fitur absensi QR scanning.","en":"Building interactive prototype with micro-interactions, transition animations, and QR scanning simulation."}'::jsonb, 4),
  ('melodean', '{"id":"Pengujian Usability & Iterasi","en":"Usability Testing & Iteration"}'::jsonb, '{"id":"Melakukan usability testing dengan siswa dan guru, mengumpulkan feedback, serta melakukan iterasi desain berdasarkan temuan testing.","en":"Conducting usability testing with students and teachers, collecting feedback, and iterating designs based on findings."}'::jsonb, 5),
  ('nusantara', '{"id":"Riset Konten & Strategi","en":"Content Research & Strategy"}'::jsonb, '{"id":"Melakukan riset mendalam tentang budaya Indonesia dan menyusun strategi konten meliputi artikel budaya, podcast sejarah, dan aktivitas interaktif.","en":"Conducting in-depth research on Indonesian culture and developing content strategy including cultural articles, history podcasts, and interactive activities."}'::jsonb, 1),
  ('nusantara', '{"id":"Arsitektur Informasi & Sitemap","en":"Information Architecture & Sitemap"}'::jsonb, '{"id":"Merancang struktur informasi website termasuk sitemap, user flow, dan hierarki konten untuk navigasi yang intuitif.","en":"Designing website information structure including sitemap, user flow, and content hierarchy for intuitive navigation."}'::jsonb, 2),
  ('nusantara', '{"id":"Wireframing & Layout","en":"Wireframing & Layout"}'::jsonb, '{"id":"Membuat wireframe untuk setiap halaman utama meliputi landing page, halaman artikel, podcast player, dan area komunitas.","en":"Creating wireframes for main pages including landing page, article page, podcast player, and community area."}'::jsonb, 3),
  ('nusantara', '{"id":"Desain Visual & UI","en":"Visual Design & UI"}'::jsonb, '{"id":"Mendesain antarmuka high-fidelity dengan nuansa budaya Indonesia yang kaya, dilengkapi tipografi dan warna yang mencerminkan identitas Nusantara.","en":"Designing high-fidelity interface with rich Indonesian cultural nuances, complemented by typography and colors reflecting Nusantara identity."}'::jsonb, 4),
  ('nusantara', '{"id":"Prototyping & Validasi","en":"Prototyping & Validation"}'::jsonb, '{"id":"Membangun prototype interaktif dan melakukan validasi desain dengan target pengguna untuk memastikan pengalaman yang optimal.","en":"Building interactive prototype and validating design with target users to ensure optimal experience."}'::jsonb, 5),
  ('paynow', '{"id":"Riset Pasar & Analisis Kompetitor","en":"Market Research & Competitor Analysis"}'::jsonb, '{"id":"Menganalisis aplikasi fintech sejenis di pasar untuk memahami standar industri, fitur unggulan, dan peluang diferensiasi produk.","en":"Analyzing similar fintech apps to understand industry standards, key features, and product differentiation opportunities."}'::jsonb, 1),
  ('paynow', '{"id":"Pemetaan User Flow","en":"User Flow Mapping"}'::jsonb, '{"id":"Merancang user flow untuk proses transfer, top-up, pembayaran tagihan, dan reward system dengan fokus pada efisiensi dan keamanan transaksi.","en":"Designing user flows for transfer, top-up, bill payment, and reward system with focus on transaction efficiency and security."}'::jsonb, 2),
  ('paynow', '{"id":"Design System UI","en":"UI Design System"}'::jsonb, '{"id":"Membangun design system komprehensif di Figma meliputi komponen finansial, color coding untuk transaksi, dan iconography khusus fintech.","en":"Building comprehensive design system in Figma including financial components, transaction color coding, and fintech-specific iconography."}'::jsonb, 3),
  ('paynow', '{"id":"Prototipe High-Fidelity","en":"High-Fidelity Prototype"}'::jsonb, '{"id":"Membuat prototype high-fidelity dengan animasi transisi antar halaman, simulasi autentikasi biometrik, dan micro-interactions pada elemen finansial.","en":"Creating high-fidelity prototype with page transition animations, biometric authentication simulation, and micro-interactions on financial elements."}'::jsonb, 4),
  ('paynow', '{"id":"Pengujian Usability & Iterasi","en":"Usability Testing & Iteration"}'::jsonb, '{"id":"Melakukan usability testing fokus pada kepercayaan dan kemudahan penggunaan, lalu iterasi berdasarkan feedback pengguna.","en":"Conducting usability testing focused on trust and ease of use, then iterating based on user feedback."}'::jsonb, 5),
  ('warasa', '{"id":"Riset Pasar & Kebutuhan Seller","en":"Market Research & Seller Needs"}'::jsonb, '{"id":"Melakukan riset kebutuhan seller Shopee meliputi tantangan optimasi produk, analisis kompetitor, dan pengelolaan toko online yang efektif.","en":"Researching Shopee seller needs including product optimization challenges, competitor analysis, and effective online store management."}'::jsonb, 1),
  ('warasa', '{"id":"Arsitektur Integrasi AI","en":"AI Integration Architecture"}'::jsonb, '{"id":"Merancang arsitektur integrasi AI/ML untuk fitur smart product generation, SEO scoring, dan analisis kompetitor berbasis Shopee API.","en":"Designing AI/ML integration architecture for smart product generation, SEO scoring, and competitor analysis via Shopee API."}'::jsonb, 2),
  ('warasa', '{"id":"Pengembangan Backend & API","en":"Backend & API Development"}'::jsonb, '{"id":"Mengembangkan backend Laravel dengan integrasi Shopee API, implementasi algoritma AI untuk rekomendasi produk, dan kalkulator ROAS.","en":"Developing Laravel backend with Shopee API integration, AI algorithms for product recommendations, and ROAS calculator."}'::jsonb, 3),
  ('warasa', '{"id":"Desain Dashboard & Mobile App","en":"Dashboard & Mobile App Design"}'::jsonb, '{"id":"Membangun dashboard web dan aplikasi mobile Flutter yang intuitif dengan visualisasi data performa produk dan tools bulk export.","en":"Building intuitive web dashboard and Flutter mobile app with product performance data visualization and bulk export tools."}'::jsonb, 4),
  ('warasa', '{"id":"Pengujian & Optimasi Performa","en":"Testing & Performance Optimization"}'::jsonb, '{"id":"Melakukan testing end-to-end pada semua fitur, optimasi performa API, dan load testing untuk memastikan skalabilitas platform.","en":"End-to-end testing on all features, API performance optimization, and load testing to ensure platform scalability."}'::jsonb, 5),
  ('spr', '{"id":"Preprocessing Data","en":"Data Preprocessing"}'::jsonb, '{"id":"Standarisasi kolom, menangani missing values, dan menyiapkan dataset sentimen musik untuk analisis.","en":"Standardizing columns, handling missing values, and preparing music sentiment dataset for analysis."}'::jsonb, 1),
  ('spr', '{"id":"Analisis Data Eksploratif","en":"Exploratory Data Analysis"}'::jsonb, '{"id":"Memvisualisasikan distribusi sentimen, distribusi genre, proporsi mood, kategori tempo, dan korelasi sentimen-genre.","en":"Visualizing sentiment distribution, genre distribution, mood proportions, tempo categories, and sentiment-genre correlations."}'::jsonb, 2),
  ('spr', '{"id":"Deteksi Emosi","en":"Emotion Detection"}'::jsonb, '{"id":"Menerapkan vektorisasi TF-IDF dan Logistic Regression untuk mengklasifikasikan input teks pengguna ke dalam kategori emosi (Happy, Sad, Motivated, Relaxed).","en":"Applying TF-IDF vectorization and Logistic Regression to classify user text input into emotion categories (Happy, Sad, Motivated, Relaxed)."}'::jsonb, 3),
  ('spr', '{"id":"Attention-Based Preference Learning","en":"Attention-Based Preference Learning"}'::jsonb, '{"id":"Menghitung bobot attention per fitur per sentimen — fitur dengan variansi lebih rendah (lebih konsisten) mendapatkan skor attention lebih tinggi.","en":"Computing attention weights per feature per sentiment — features with lower variance (more consistent) receive higher attention scores."}'::jsonb, 4),
  ('spr', '{"id":"Content-Based Filtering","en":"Content-Based Filtering"}'::jsonb, '{"id":"Membangun cosine similarity berbobot menggunakan attention weights untuk menemukan lagu yang paling relevan dengan profil emosi yang terdeteksi.","en":"Building weighted cosine similarity using attention weights to find songs most relevant to the detected emotion profile."}'::jsonb, 5),
  ('spr', '{"id":"Explainable AI & Visualisasi","en":"Explainable AI & Visualization"}'::jsonb, '{"id":"Menghasilkan breakdown kontribusi fitur per lagu, analisis kata attention, dan heatmap XAI yang menjelaskan mengapa setiap lagu direkomendasikan.","en":"Generating per-song feature contribution breakdowns, attention word analysis, and XAI heatmaps explaining why each song is recommended."}'::jsonb, 6),
  ('spr', '{"id":"Evaluasi","en":"Evaluation"}'::jsonb, '{"id":"Mengevaluasi performa sistem menggunakan metrik Precision@K, Recall@K, Hit Rate, MAP, dan NDCG pada K=3, K=5, dan K=7.","en":"Evaluating system performance using Precision@K, Recall@K, Hit Rate, MAP, and NDCG metrics at K=3, K=5, and K=7."}'::jsonb, 7),
  ('pixora', '{"id":"Analisis Kebutuhan & Perancangan","en":"Requirements Analysis & Design"}'::jsonb, '{"id":"Menganalisis kebutuhan platform booking studio fotografi, merancang database relasional (users, packages, bookings, payments), serta menyusun arsitektur integrasi web dan mobile.","en":"Analyzing photography studio booking platform needs, designing relational database (users, packages, bookings, payments), and planning web-mobile integration architecture."}'::jsonb, 1),
  ('pixora', '{"id":"Pengembangan Backend Laravel","en":"Laravel Backend Development"}'::jsonb, '{"id":"Membangun backend Laravel dengan autentikasi multi-role (admin/customer), CRUD paket fotografi, sistem booking dengan validasi ketersediaan jadwal, dan REST API untuk aplikasi mobile.","en":"Building Laravel backend with multi-role authentication (admin/customer), photography package CRUD, booking system with schedule validation, and REST API for mobile app."}'::jsonb, 2),
  ('pixora', '{"id":"Integrasi Payment Gateway","en":"Payment Gateway Integration"}'::jsonb, '{"id":"Mengintegrasikan Midtrans Snap untuk pembayaran online mendukung Virtual Account, E-Wallet, dan QRIS, lengkap dengan webhook notification dan invoice PDF otomatis.","en":"Integrating Midtrans Snap for online payments supporting Virtual Account, E-Wallet, and QRIS, with webhook notifications and automatic PDF invoices."}'::jsonb, 3),
  ('pixora', '{"id":"Pengembangan Mobile App Flutter","en":"Flutter Mobile App Development"}'::jsonb, '{"id":"Membangun aplikasi mobile menggunakan Flutter dengan Provider state management, fitur browse paket, kalender booking, pembayaran via WebView, chatbot AI, dan Google Sign-In.","en":"Building mobile app using Flutter with Provider state management, package browsing, booking calendar, WebView payments, AI chatbot, and Google Sign-In."}'::jsonb, 4),
  ('pixora', '{"id":"Integrasi AI & Testing","en":"AI Integration & Testing"}'::jsonb, '{"id":"Mengintegrasikan AI assistant untuk FAQ dan bantuan booking, melakukan pengujian end-to-end pada alur booking dan pembayaran di web maupun mobile, serta optimasi performa.","en":"Integrating AI assistant for FAQ and booking help, end-to-end testing on booking and payment flows for web and mobile, and performance optimization."}'::jsonb, 5),
  ('qa-cazh', '{"id":"Analisis Requirements & Dokumen","en":"Requirements Analysis & Documentation"}'::jsonb, '{"id":"Mempelajari dokumen spesifikasi produk, user story, dan acceptance criteria untuk memahami fitur yang akan diuji.","en":"Studying product specification documents, user stories, and acceptance criteria to understand features to be tested."}'::jsonb, 1),
  ('qa-cazh', '{"id":"Penyusunan Test Case & Test Scenario","en":"Test Case & Test Scenario Design"}'::jsonb, '{"id":"Merancang test case dan test scenario yang komprehensif mencakup positive testing, negative testing, dan edge case untuk setiap fitur.","en":"Designing comprehensive test cases and test scenarios covering positive testing, negative testing, and edge cases for each feature."}'::jsonb, 2),
  ('qa-cazh', '{"id":"Eksekusi Pengujian Fungsional","en":"Functional Testing Execution"}'::jsonb, '{"id":"Menjalankan pengujian fungsional secara manual pada setiap modul produk digital, memverifikasi kesesuaian dengan spesifikasi yang telah ditentukan.","en":"Executing manual functional testing on each digital product module, verifying compliance with defined specifications."}'::jsonb, 3),
  ('qa-cazh', '{"id":"Pelaporan Bug & Tracking","en":"Bug Reporting & Tracking"}'::jsonb, '{"id":"Mendokumentasikan dan melaporkan bug yang ditemukan melalui bug tracking system dengan detail steps to reproduce, severity, dan priority.","en":"Documenting and reporting found bugs through bug tracking system with detailed steps to reproduce, severity, and priority."}'::jsonb, 4),
  ('qa-cazh', '{"id":"Regression Testing & Validasi","en":"Regression Testing & Validation"}'::jsonb, '{"id":"Melakukan regression testing setelah perbaikan bug untuk memastikan tidak ada fitur lain yang terdampak, serta validasi akhir sebelum rilis ke production.","en":"Performing regression testing after bug fixes to ensure no other features are affected, and final validation before production release."}'::jsonb, 5)
